// OV-1741: a Legend edit lays the gradient blocks out again, inside as well
// as their group. A Result saved by an earlier version (its gradient parts at
// the old geometry) and a renamed gradient title get, from the Web Legend
// layout, the title, bar, and scale-label positions Python draws for the same
// rows at the next Generate. The expected positions are Python's: those its
// writer drew in a Gallery Result (an unchanged Legend), or those Python's
// layout gives in tests/fixtures/legend_layout_vectors.json (renamed titles,
// Circular blocks), generated by tools/generate_legend_layout_vectors.py.
import assert from 'node:assert/strict';
import { savedDrawingView } from './helpers/saved-drawing-view.mjs';
import { readFileSync } from 'node:fs';
import test from 'node:test';
import { gunzipSync } from 'node:zlib';

import { installFakeSvgDom } from './fake-svg-dom.mjs';

installFakeSvgDom();
globalThis.CSS ||= { escape: (value) => String(value) };

const { createLegendLayoutActions } = await import('../../gbdraw/web/js/app/legend/layout-actions.js');

const vectors = JSON.parse(readFileSync(new URL('../fixtures/legend_layout_vectors.json', import.meta.url), 'utf8'));
const vector = (name, edit) => {
  const found = vectors.layout.find((entry) => entry.name === name && entry.edit === edit);
  assert.ok(found, `vector ${name} / ${edit}`);
  return found;
};
const COMPOSITION = 'data-gbdraw-composition';
const decodeAttribute = (value) => value.replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&amp;/g, '&');

const galleryContent = (base) => {
  const path = new URL(`../../gbdraw/web/gallery/sessions/${base}.gbdraw-session.json.gz`, import.meta.url);
  const saved = JSON.parse(gunzipSync(readFileSync(path)).toString('utf8'));
  return savedDrawingView(saved, saved.ui.activeDrawingId).results[0].content;
};
const SCHEMA = 'data-gbdraw-composition-schema';
// The fake DOM keeps attribute text as written; the layout reads the metadata as the DOM decodes it.
const parseSvg = (content) => {
  const svg = new DOMParser().parseFromString(content, 'image/svg+xml').documentElement;
  svg.setAttribute(COMPOSITION, decodeAttribute(svg.getAttribute(COMPOSITION)));
  return svg;
};

const translateOf = (element) => {
  const match = String(element?.getAttribute('transform') || '').match(/translate\(\s*([-+.\deE]+)\s*[, ]\s*([-+.\deE]+)\s*\)/);
  assert.ok(match, `no translate on ${element?.localName}`);
  return [Number(match[1]), Number(match[2])];
};
// Every title, bar, and scale label of the gradient groups, in document order.
const gradientParts = (svg) => Array.from(svg.querySelectorAll('[data-gbdraw-role="comparison-legend"]'))
  .flatMap((group) => group.querySelectorAll('text, path')
    .map((part) => [group.id, part.localName, part.textContent, ...translateOf(part)]));
// An earlier version's geometry: every part of every gradient block elsewhere.
const shiftGradientParts = (svg, dx, dy) => {
  svg.querySelectorAll('[data-gbdraw-role="comparison-legend"]').forEach((group) => {
    group.querySelectorAll('text, path').forEach((part) => {
      const [x, y] = translateOf(part);
      part.setAttribute('transform', `translate(${x + dx}, ${y + dy})`);
    });
  });
};
const layOut = () => {
  const actions = createLegendLayoutActions({ readRegisteredFontFaces: () => [] });
  return actions;
};

for (const base of ['hepatoplasmataceae_collinear', 'majanivirus_orthogroup']) {
  test(`OV-1741: the first Legend edit of an old Linear Result places its gradient parts as Python does (${base})`, async () => {
    const svg = parseSvg(galleryContent(base));
    const drawn = gradientParts(svg);
    assert.ok(drawn.length >= 8, 'both orientations draw a gradient block');
    shiftGradientParts(svg, 7, -3);
    const actions = layOut();
    await actions.prepareLegendLayout();
    assert.ok(actions.layOutLegend(svg));
    assert.deepEqual(gradientParts(svg), drawn);
  });
}

test('OV-1741: a renamed single Linear gradient title moves its title, bar, and scale labels as Python lays them out', async () => {
  const source = vector('majanivirus_orthogroup#0', 'rename the gradient title');
  const renamed = source.rows.find((row) => row.type === 'gradient').key;
  const svg = parseSvg(galleryContent('majanivirus_orthogroup'));
  const titles = Array.from(svg.querySelectorAll('[data-gbdraw-role="comparison-legend"] g[data-legend-key]'))
    .map((entry) => entry.querySelector('text'));
  assert.equal(titles.length, 2);
  titles.forEach((title) => { title.textContent = renamed; });
  const actions = layOut();
  await actions.prepareLegendLayout();
  assert.ok(actions.layOutLegend(svg));

  for (const [name, suffix] of [['horizontal', 'h'], ['vertical', 'v']]) {
    const gradient = source.expected[name].gradient;
    const [entry] = gradient.entries;
    assert.ok(entry.barX > 0, 'the title is wider than the bar');
    const group = svg.querySelector(`#pairwise_legend_${suffix}`);
    const [title, minLabel, maxLabel] = group.querySelectorAll('text');
    assert.deepEqual(translateOf(title), [entry.titleX, entry.titleY], `${name} title`);
    assert.deepEqual(translateOf(group.querySelector('path[fill^="url("]')), [entry.barX, entry.barY], `${name} bar`);
    assert.deepEqual(translateOf(minLabel), [gradient.minLabelX, gradient.scaleLabelY], `${name} minimum label`);
    assert.deepEqual(translateOf(maxLabel), [gradient.maxLabelX, gradient.scaleLabelY], `${name} 100% label`);
  }
});

// A Circular gradient Legend as Python's writer (render/groups/circular/legend.py)
// draws it, with every part at (0, 0): the Legend of an earlier version.
const circularGradientSvg = (options, rows, minLabel) => {
  const circular = parseSvg(galleryContent('Vnig_TUMSAT-TG-2018'));
  const metadata = JSON.parse(circular.getAttribute(COMPOSITION));
  assert.ok(metadata.legendReflow, 'a current Circular Result records its Legend inputs');
  metadata.legendSide = options.side;
  metadata.legendReflow = { ...metadata.legendReflow, fontFile: options.fontFile, fontSize: options.fontSize,
    colorRectSize: options.colorRectSize, wrapWidth: options.wrapWidth };
  const text = (content, anchor) => `<text font-family="${options.fontFamily}" font-size="${options.fontSize}" `
    + `text-anchor="${anchor}" transform="translate(0,0)">${content}</text>`;
  const bar = (id) => `<path d="M 0,0 L 1,0 z" fill="url(#${id})" stroke="none" stroke-width="0" transform="translate(0,0)" />`;
  const scale = text(minLabel, 'start') + text('100%', 'end');
  const gradients = rows.filter((row) => row.type === 'gradient');
  const entries = gradients.map((row, index) => `<g data-legend-key="${row.key}"><linearGradient id="g${index}">`
    + `<stop offset="0%" stop-color="#fff" /></linearGradient>${text(row.name, gradients.length > 1 ? 'start' : 'middle')}`
    + `${bar(`g${index}`)}${gradients.length > 1 ? '' : scale}</g>`).join('');
  const content = `<svg xmlns="http://www.w3.org/2000/svg" ${COMPOSITION}="" ${SCHEMA}="${circular.getAttribute(SCHEMA)}">`
    + '<g id="legend"><path d="M 0,0 z" fill="none" stroke="none" stroke-width="0" />'
    + '<g id="conservation_identity_legend" data-gbdraw-role="comparison-legend" data-gbdraw-orientation="circular">'
    + `${entries}${gradients.length > 1 ? scale : ''}</g></g></svg>`;
  const svg = new DOMParser().parseFromString(content, 'image/svg+xml').documentElement;
  svg.setAttribute(COMPOSITION, JSON.stringify(metadata));
  return svg;
};

test('OV-1741: a Circular single gradient laid out again takes Python\'s title, bar, and scale-label positions', async () => {
  const source = vector('synthetic circular', 'one gradient with a title wider than its bar, left');
  const rows = source.rows.map((row) => ({ ...row, name: row.key }));
  const svg = circularGradientSvg(source.options, rows, source.expected.gradient.minLabelText);
  const actions = layOut();
  await actions.prepareLegendLayout();
  assert.ok(actions.layOutLegend(svg));
  const gradient = source.expected.gradient;
  const [entry] = gradient.singleEntries;
  const block = svg.querySelector('#conservation_identity_legend');
  const [title, minLabel, maxLabel] = block.querySelectorAll('text');
  assert.deepEqual(translateOf(title), [entry.titleX, entry.titleY]);
  assert.deepEqual(translateOf(block.querySelector('path[fill^="url("]')), [entry.barX, entry.barY]);
  assert.deepEqual(translateOf(minLabel), [gradient.minLabelX, gradient.scaleLabelY]);
  assert.deepEqual(translateOf(maxLabel), [gradient.maxLabelX, gradient.scaleLabelY]);
});

test('OV-1741: a Circular compact gradient block laid out again takes Python\'s label, bar, and scale positions', async () => {
  const source = vector('synthetic circular', 'solid rows and two gradients, left');
  const rows = source.rows.map((row) => ({ ...row, name: row.key }));
  const gradient = source.expected.gradient;
  const svg = circularGradientSvg(source.options, rows, gradient.minLabelText);
  const actions = layOut();
  await actions.prepareLegendLayout();
  assert.ok(actions.layOutLegend(svg));
  const block = svg.querySelector('#conservation_identity_legend');
  const entries = block.children.filter((child) => child.localName === 'g');
  assert.equal(entries.length, gradient.compactEntries.length);
  gradient.compactEntries.forEach((expected, index) => {
    assert.equal(entries[index].getAttribute('data-legend-key'), expected.key);
    assert.deepEqual(translateOf(entries[index].querySelector('text')), [expected.labelX, expected.labelY], `${expected.key} label`);
    assert.deepEqual(translateOf(entries[index].querySelector('path')), [gradient.barX, expected.barY], `${expected.key} bar`);
  });
  const [minLabel, maxLabel] = block.children.filter((child) => child.localName === 'text');
  assert.deepEqual(translateOf(minLabel), [gradient.minLabelX, gradient.scaleLabelY]);
  assert.deepEqual(translateOf(maxLabel), [gradient.maxLabelX, gradient.scaleLabelY]);
});

// PD-OI-110: the similarity-ring block, as Python writes it (render/groups/circular/legend.py), laid out again
// from wrong positions, takes the positions Python's layout gives (tests/fixtures/legend_layout_vectors.json).
// `captions`: whether Python drew `outer` and `inner`; a ring row with a color draws its own ramp (gradient, bar,
// name), a row with `swatch` the solid swatch of scenario revision 1, and the identity scale draws the one band only
// when no row has a color.
const ringBlockSvg = (options, rows, minLabel, tail = '', captions = true) => {
  const svg = circularGradientSvg(options, [], minLabel);
  const text = (content, anchor = 'start') => `<text font-family="${options.fontFamily}" font-size="${options.fontSize}" `
    + `text-anchor="${anchor}" transform="translate(3,4)">${content}</text>`;
  const ramp = (index, color) => `<linearGradient id="ramp${index}"><stop offset="0%" stop-color="#fff" />`
    + `<stop offset="100%" stop-color="${color}" /></linearGradient>`
    + `<path d="M 0,0 z" fill="url(#ramp${index})" stroke="none" stroke-width="0" transform="translate(3,4)" />`;
  const swatch = (fill) => `<path d="M 0,0 z" fill="${fill}" stroke="none" stroke-width="0" transform="translate(3,4)" />`;
  const solids = rows.filter((row) => row.type === 'solid').map((row) => `<g data-legend-key="${row.key}">`
    + `<path d="M 0,0 z" fill="#000" stroke="${row.stroke}" stroke-width="${row.strokeWidth}" transform="translate(3,4)" />`
    + `${text(row.name)}</g>`).join('');
  const ringRows = rows.filter((row) => row.type === 'ring');
  const rings = ringRows.map((row, index) => `<g data-legend-key="${row.key}" `
    + `data-source-index="${index}" data-track-index="${index + 1}">`
    + `${row.color ? ramp(index, row.color) : ''}${row.swatch ? swatch(row.swatch) : ''}${text(row.name)}</g>`).join('');
  const band = ringRows.some((row) => row.color) ? '' : '<linearGradient id="band"><stop offset="0%" stop-color="#fff" />'
    + '</linearGradient><path d="M 0,0 z" fill="url(#band)" stroke="none" stroke-width="0" transform="translate(3,4)" />';
  const scale = `<g data-gbdraw-role="conservation-identity-band">${band}${text('identity')}${text(minLabel)}${text('100%', 'end')}</g>`;
  const content = '<svg xmlns="http://www.w3.org/2000/svg"><g id="legend"><path d="M 0,0 z" fill="none" stroke="none" stroke-width="0" />'
    + `${solids ? `<g id="feature_legend">${solids}</g>` : ''}`
    + '<g id="conservation_identity_legend" data-gbdraw-role="comparison-legend" data-gbdraw-orientation="circular">'
    + `${captions ? text('outer') : ''}${rings}${captions ? text('inner') : ''}${scale}${tail}</g></g></svg>`;
  const ringSvg = new DOMParser().parseFromString(content, 'image/svg+xml').documentElement;
  ringSvg.setAttribute(COMPOSITION, svg.getAttribute(COMPOSITION));
  ringSvg.setAttribute(SCHEMA, svg.getAttribute(SCHEMA) || '');
  return ringSvg;
};

for (const edit of [
  'solid rows and rings of several colors, left',
  'solid rows and rings that share colors, left',
  'solid rows and one-color rings, top'
]) {
  test(`PD-OI-110: a similarity-ring block laid out again takes Python's positions (${edit})`, async () => {
    const source = vector('synthetic circular', edit);
    const rings = source.expected.rings;
    const svg = ringBlockSvg(
      source.options, source.rows.map((row) => ({ ...row, name: row.key })), rings.minLabelText, '', rings.showCaptions
    );
    const actions = layOut();
    await actions.prepareLegendLayout();
    assert.ok(actions.layOutLegend(svg));
    const block = svg.querySelector('#conservation_identity_legend');
    assert.deepEqual(translateOf(block), [source.expected.gradientX, source.expected.gradientY]);
    const captions = block.children.filter((child) => child.localName === 'text');
    if (rings.showCaptions) {
      assert.deepEqual(captions.map((caption) => translateOf(caption)), [[0, rings.outerCaptionY], [0, rings.innerCaptionY]]);
    } else {
      assert.deepEqual(captions, []);
    }
    const rows = block.children.filter((child) => child.localName === 'g' && child.hasAttribute('data-legend-key'));
    assert.equal(rows.length, rings.rows.length);
    rings.rows.forEach((expected, index) => {
      assert.equal(rows[index].getAttribute('data-legend-key'), expected.key);
      assert.deepEqual(translateOf(rows[index].querySelector('text')), [0, expected.y], `${expected.key} name`);
      const ramp = rows[index].querySelector('path');
      assert.equal(Boolean(ramp), rings.bandY === null, `${expected.key} ramp`);
      if (ramp) assert.deepEqual(translateOf(ramp), [rings.barX, expected.y], `${expected.key} ramp`);
    });
    const scale = block.querySelector('[data-gbdraw-role="conservation-identity-band"]');
    const band = scale.querySelector('path');
    assert.equal(Boolean(band), rings.bandY !== null);
    if (band) assert.deepEqual(translateOf(band), [0, rings.bandY]);
    const [label, minLabel, maxLabel] = scale.children.filter((child) => child.localName === 'text');
    assert.deepEqual(translateOf(label), [rings.identityLabelX, rings.identityLabelY]);
    assert.deepEqual(translateOf(minLabel), [rings.minLabelX, rings.scaleLabelY]);
    assert.deepEqual(translateOf(maxLabel), [rings.maxLabelX, rings.scaleLabelY]);
  });
}

// A Result drawn before PD-OI-110 scenario revision 2 shows a color swatch on each ring row of rings that differ
// in color; Python's layout no longer gives that form, so the Web leaves the Legend where Python drew it.
test('PD-OI-110: a ring block drawn with swatches (scenario revision 1) is left where Python drew it', async () => {
  const source = vector('synthetic circular', 'solid rows and rings of several colors, left');
  const rows = source.rows.map((row) => ({ ...row, name: row.key, color: null, swatch: row.color }));
  const svg = ringBlockSvg(source.options, rows, '90%');
  const ring = svg.querySelector('#conservation_identity_legend g[data-track-index]');
  const actions = layOut();
  await actions.prepareLegendLayout();
  assert.equal(actions.layOutLegend(svg), null);
  assert.deepEqual(translateOf(ring.querySelector('text')), [3, 4]);
});

// The Circular side block as Python writes it now: the ring block, then the gradient rows (an annotation
// gradient names its scale's ends on its entry), then one scale line per group of rows that share scale texts.
test('the gradient rows below a ring block, of two scales, take Python\'s positions', async () => {
  const source = vector('synthetic circular', 'rings and two gradients of two scales, left');
  const rows = source.rows.map((row) => ({ ...row, name: row.key }));
  const { rings, gradient } = source.expected;
  assert.ok(rings && gradient && gradient.moreScales.length === 1);
  const text = (content, anchor = 'start') => `<text font-family="${source.options.fontFamily}" `
    + `font-size="${source.options.fontSize}" text-anchor="${anchor}" transform="translate(3,4)">${content}</text>`;
  const entries = rows.filter((row) => row.type === 'gradient').map((row, index) => `<g data-legend-key="${row.key}"`
    + `${row.minLabel ? ` data-legend-min-label="${row.minLabel}" data-legend-max-label="${row.maxLabel}"` : ''}>`
    + `<linearGradient id="r${index}"><stop offset="0%" stop-color="#fff" /></linearGradient>${text(row.name)}`
    + `<path d="M 0,0 z" fill="url(#r${index})" stroke="none" stroke-width="0" transform="translate(3,4)" /></g>`).join('');
  const scales = [gradient, ...gradient.moreScales].map((scale) => text(scale.minLabelText) + text(scale.maxLabelText, 'end'));
  const svg = ringBlockSvg(source.options, rows, rings.minLabelText, entries + scales.join(''));
  const actions = layOut();
  await actions.prepareLegendLayout();
  assert.ok(actions.layOutLegend(svg));
  const block = svg.querySelector('#conservation_identity_legend');
  assert.deepEqual(translateOf(block), [source.expected.gradientX, source.expected.gradientY]);
  const byKey = new Map(block.children.filter((child) => child.localName === 'g' && child.hasAttribute('data-legend-key'))
    .map((entry) => [entry.getAttribute('data-legend-key'), entry]));
  gradient.compactEntries.forEach((expected) => {
    const entry = byKey.get(expected.key);
    assert.deepEqual(translateOf(entry.querySelector('text')), [expected.labelX, expected.labelY], `${expected.key} label`);
    assert.deepEqual(translateOf(entry.querySelector('path')), [gradient.barX, expected.barY], `${expected.key} bar`);
  });
  const labels = block.children.filter((child) => child.localName === 'text').slice(-4);
  [gradient, ...gradient.moreScales].forEach((scale, index) => {
    assert.equal(labels[2 * index].textContent, scale.minLabelText);
    assert.deepEqual(translateOf(labels[2 * index]), [scale.minLabelX, scale.scaleLabelY]);
    assert.deepEqual(translateOf(labels[(2 * index) + 1]), [scale.maxLabelX, scale.scaleLabelY]);
  });
  const [outer, inner] = block.children.filter((child) => child.localName === 'text');
  assert.deepEqual(translateOf(outer), [0, rings.outerCaptionY]);
  assert.deepEqual(translateOf(inner), [0, rings.innerCaptionY]);
});

// The fake DOM's textContent, which the cases above read and write, keeps
// mixed content in document order.
test('fake SVG DOM: textContent reads mixed content in document order', () => {
  const svg = new DOMParser().parseFromString(
    '<svg xmlns="http://www.w3.org/2000/svg"><text>a<tspan>b</tspan>c&amp;d</text></svg>', 'image/svg+xml'
  ).documentElement;
  const text = svg.querySelector('text');
  assert.equal(text.textContent, 'abc&d');
  text.textContent = 'x<y';
  assert.equal(text.textContent, 'x<y');
  assert.equal(text.children.length, 0);
});
